#!/bin/bash  HeliosLM v4.1 GitHub Push Script  Usage: 1. Create a GitHub Personal Access Token (Settings -> Developer settings -> Tokens) 2. Create a new empty repository on GitHub (do NOT initialize with README) 3. Run: ./push_to_github.sh  set -e  echo  HeliosLM v4.1 GitHub Push Script  echo  ============================================   Check if we're in the right directory if [ ! -d .git ]; then   echo  Error: Not a git repository. Run this from /mnt/agents/output/   exit 1 fi  REMOTE_URL=  Read GitHub credentials read -p  GitHub repository URL (e.g., https://github.com/username/helioslm.git):  REMOTE_URL  if [ -z $REMOTE_URL ]; then   echo  Error: Repository URL is required   exit 1 fi  Check if URL contains token if [[ $REMOTE_URL == https://*@* ]]; then   echo  Using HTTPS with embedded token...  else   read -sp  GitHub Personal Access Token (optional, press Enter to use SSH):  TOKEN   if [ -n $TOKEN ]; then     # Convert https://github.com/user/repo.git to https://TOKEN@github.com/user/repo.git     REMOTE_URL=$(echo $REMOTE_URL | sed 's|https://|https://'$TOKEN'@|')     echo      echo  Using HTTPS with token authentication...    else     echo      echo  Using SSH authentication... Make sure your SSH key is added to GitHub.   fi fi  Set remote and push echo  Adding remote origin...  git remote remove origin 2>/dev/null || true git remote add origin $REMOTE_URL  echo  Pushing to GitHub...  git push -u origin main --force  echo  echo  Successfully pushed HeliosLM v4.1 to GitHub!  echo  Repository: $REMOTE_URL  echo  echo  Files pushed: $(git ls-files | wc -l)  echo  Total commits: $(git rev-list --count HEAD)  echo  echo  Next steps:  echo  1. Visit your GitHub repository to verify  echo  2. Enable GitHub Actions if you have CI workflows  echo  3. Add repository secrets for deployment  echo  4. Configure branch protection rules for main  